```javascript
import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, Color, Vector3 } from 'three/webgpu';
import { gsap } from 'gsap';
import { uv, vec3, mix, uniform, positionWorld, normalWorld, cameraPosition, dot, normalize, reflect, pow, saturate, max, abs, step, smoothstep, length, add, mul, sub, div, texture, sampler, screenUV, viewport } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Dimensions ---
  const BAND_W = 6.8;
  const BAND_H = 2.0;
  const HAIRLINE = 0.006;
  const BASELINE = 0.25;
  const COLUMN_W = 1.2;
  const GUTTER = 0.375;
  const COLUMN_GAP = COLUMN_W + GUTTER;
  const WORDMARK_W = 2.0;
  const ACCENT_BAR_W = 0.3;
  const ACCENT_BAR_H = 0.02;
  const LEGAL_Y_FROM_BOTTOM = 0.375;
  const HAIRLINE_CLEARANCE = 0.25;

  // --- Backdrop plane ---
  const geo = new PlaneGeometry(BAND_W, BAND_H);
  const mat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    side: ctx.THREE.DoubleSide,
  });

  // Vertical gradient using TSL
  const vUv = uv();
  const gradientTop = new Color('#121218');
  const gradientBottom = new Color('#0b0b10');
  const gradientMix = mix(
    vec3(gradientTop.r, gradientTop.g, gradientTop.b),
    vec3(gradientBottom.r, gradientBottom.g, gradientBottom.b),
    vUv.y
  );
  mat.colorNode = vec3(gradientMix);

  // Key light grazing from upper left for specular edge on hairline rules
  const lightDir = normalize(vec3(-1.0, 1.0, 0.5));
  const N = normalWorld;
  const V = normalize(sub(cameraPosition, positionWorld));
  const H = normalize(add(lightDir, V));
  const spec = pow(max(dot(N, H), 0.0), 32.0);
  mat.emissiveNode = mul(spec, 0.15);

  const plane = new Mesh(geo, mat);
  plane.position.set(0, 0, 0);
  group.add(plane);

  // --- Top hairline rule ---
  const hairlineGeo = new PlaneGeometry(BAND_W - 0.2, HAIRLINE);
  const hairlineMat = new MeshStandardNodeMaterial({
    color: new Color('#23232b'),
    roughness: 0.4,
    metalness: 0.3,
    emissive: new Color('#23232b'),
    emissiveIntensity: 0.1,
  });
  const topHairline = new Mesh(hairlineGeo, hairlineMat);
  topHairline.position.set(0, BAND_H / 2 - HAIRLINE / 2, 0.001);
  group.add(topHairline);

  // --- Bottom hairline rule ---
  const bottomHairline = new Mesh(hairlineGeo.clone(), hairlineMat.clone());
  bottomHairline.position.set(0, -BAND_H / 2 + LEGAL_Y_FROM_BOTTOM + HAIRLINE_CLEARANCE + HAIRLINE / 2, 0.001);
  group.add(bottomHairline);

  // --- Wordmark block (left 2.0 units) ---
  const wordmarkX = -BAND_W / 2 + 0.5;
  const wordmarkY = BAND_H / 2 - 0.5;

  const wordmarkText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 34,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.02 * 34,
  });
  wordmarkText.position.set(wordmarkX, wordmarkY, 0.002);
  group.add(wordmarkText);

  // Accent bar beneath wordmark
  const accentBarGeo = new PlaneGeometry(ACCENT_BAR_W, ACCENT_BAR_H);
  const accentBarMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 1.4,
    roughness: 0.3,
    metalness: 0.1,
  });
  const accentBar = new Mesh(accentBarGeo, accentBarMat);
  accentBar.position.set(wordmarkX + ACCENT_BAR_W / 2, wordmarkY - 0.15, 0.002);
  group.add(accentBar);

  // --- Link columns ---
  const columns = [
    {
      header: 'ATELIER',
      links: ['Features', 'Collection', 'Pricing'],
    },
    {
      header: 'COMPANY',
      links: ['Journal', 'Visit the Atelier', 'Contact'],
    },
    {
      header: 'LEGAL',
      links: ['Privacy', 'Terms', 'Warranty'],
    },
  ];

  const columnStartX = -BAND_W / 2 + 2.5;
  const columnY = BAND_H / 2 - 0.5;

  columns.forEach((col, colIdx) => {
    const colX = columnStartX + colIdx * COLUMN_GAP;

    // Column header
    const headerText = ctx.fontAtlas.createText(col.header, {
      fontSize: 9,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: 0.12 * 9,
    });
    headerText.position.set(colX, columnY, 0.002);
    group.add(headerText);

    // Links
    col.links.forEach((linkText, linkIdx) => {
      const linkObj = ctx.fontAtlas.createText(linkText, {
        fontSize: 13,
        color: '#e8ecf2',
        align: 'left',
        letterSpacingPx: 0,
      });
      const linkY = columnY - 0.25 - (linkIdx + 1) * 0.25 * 1.8;
      linkObj.position.set(colX, linkY, 0.002);
      group.add(linkObj);

      // Hover handler
      linkObj.userData.handlers = linkObj.userData.handlers || {};
      linkObj.userData.handlers.mouseenter = () => {
        gsap.to(linkObj.position, {
          z: 0.02,
          duration: 0.14,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        if (linkObj.material) {
          gsap.to(linkObj.material, {
            color: '#ff2a38',
            duration: 0.14,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          });
        }
      };
      linkObj.userData.handlers.mouseleave = () => {
        gsap.to(linkObj.position, {
          z: 0,
          duration: 0.14,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
        if (linkObj.material) {
          gsap.to(linkObj.material, {
            color: '#e8ecf2',
            duration: 0.14,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
          });
        }
      };
    });
  });

  // --- Legal line ---
  const legalText = ctx.fontAtlas.createText('(c) 2026 Nova Atelier. All rights reserved. Machined in Geneva.', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.04 * 9,
  });
  legalText.position.set(0, -BAND_H / 2 + LEGAL_Y_FROM_BOTTOM / 2, 0.002);
  group.add(legalText);

  // --- Entrance animation ---
  group.opacity = 0;
  group.position.y = -0.2;
  const tl = gsap.timeline();
  tl.to(group, {
    opacity: 1,
    y: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  });

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    mat.dispose();
    hairlineGeo.dispose();
    hairlineMat.dispose();
    accentBarGeo.dispose();
    accentBarMat.dispose();
    group.children.forEach(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  };

  return group;
}
